local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine'
local KTool = CS.Engine.Lib.KTool


---@type RegressionActivityConstants
local RegressionActivityConstants = import("Game.Activity.RegressionActivity.RegressionActivityConstants")
local TabGroupPath = "Game.Activity.RegressionActivity.RegressionTabToggleLeft"
--- from: Assets/BundleResources/Prefabs/RegressionNew/RegressionNewDialog5010.prefab > name: RegressionNewDialog5010
---@class RegressionNewDialog
---@field Env                           	RegressionNewDialog                     
---@field controller                    	Engine.UI.UILuaDialog                   
---@field RewardRoot                    	UnityEngine.RectTransform               	@ 0    
---@field TxtTime                       	UnityEngine.RectTransform               	@ 1    
---@field TabLeftGroup                  	UnityEngine.RectTransform               	@ 2    
local RegressionNewDialog = Class("RegressionNewDialog")

---@type RegressionUtils
local RegressionUtils = import('Game.Activity.RegressionActivity.RegressionUtils')

function RegressionNewDialog:__init()
	self._toggleData      = {}        --页签是数据
	self._curActivityId   = 0         --当前选择的活动id
	self._activityNodes   = {}
end

function RegressionNewDialog:__delete()
	if self.redPointRefresh then
		Events.RemoveListener(Constants.EventNames.REFRESH_NEW_REGRESSION_RED_POINT,self.redPointRefresh)
		self.redPointRefresh = nil
	end
end

function RegressionNewDialog:Awake()
	self.redPointRefresh = Events.AddListener(Constants.EventNames.REFRESH_NEW_REGRESSION_RED_POINT, Bind(self, self.RefreshRedPoint))
end

function RegressionNewDialog:OnFocus(focus)
	if focus then
		local node = self._activityNodes[tostring(self._selectedIndex)]
		if node and not isNull(node.go) and node.scr then
			if node.scr.RefreshTopGoods then
				node.scr:RefreshTopGoods()
			end
		end
	end
end

function RegressionNewDialog:InitToggleData()
	self._toggleData    = {}
	self._selectedIndex = 1
	
	local config = RegressionActivityConstants.Configs
	for i, v in pairs(config) do
		local dojo = v
		dojo.type = checkNumber(i)
		local redPointStatus = self:GetRedPointStatus(dojo.type)
		table.insert(self._toggleData, {
			text = v.name,
			iconPath = v.iconPath,
			dojo = dojo,
			redPointStatus = redPointStatus,
			func = function()
				self:RefreshNode(dojo.type)
			end,
		})
	end
	
	table.sort(self._toggleData,function(a,b)
		return a.dojo.type < b.dojo.type
	end )
end

function RegressionNewDialog:GetRedPointStatus(type)
	local redPoint = false
	local type = tostring(type)
	if type == RegressionActivityConstants.ActivityType.Battle then
		redPoint = RegressionUtils.GetRegressMgr():CheckBattleRedPoint()
	elseif type == RegressionActivityConstants.ActivityType.DailySin then
		redPoint = RegressionUtils.GetRegressMgr():CheckDailySignRedPoint()
	elseif type == RegressionActivityConstants.ActivityType.Task then
		redPoint = RegressionUtils.GetRegressMgr():CheckTaskRedPoint()
	elseif type == RegressionActivityConstants.ActivityType.Gift then
		redPoint = RegressionUtils.GetRegressMgr():CheckGiftRedPoint()
	end
	return redPoint
end

function RegressionNewDialog:FillSelf()
	---@type CommonTabToggleLeft
	local scr = CfUtils.GetLuaScr(self.TabLeftGroup, TabGroupPath)
	if scr then
		scr:FillToggles(self._toggleData, self._selectedIndex)
		scr:MoeToItemByIndex(self._selectedIndex)
	end
	self:RefreshNode(self._selectedIndex)
end

--刷新节点
function RegressionNewDialog:RefreshNode(index)
	if checkNumber(index) == 0 then
		return
	end
	local data = self._toggleData[checkNumber(index)]
	--先注销当前选择的
	if checkNumber(self._selectedIndex) ~= 0 then
		local toggleData = self._toggleData[self._selectedIndex].dojo
		local node = self._activityNodes[tostring(toggleData.type)]
		if node and node.go then
			--node.go.transform.anchoredPosition3D = Vector3(0, 0, 0)
			self:SetCanvasEnabled(node, false)
		end
	end
	self._selectedIndex = index
	self:ShowActivityNode(data)
end

function RegressionNewDialog:ShowActivityNode(data)
	if not data then return end
	-- 还原顶部导航栏
	--ActivityUtils.RefreshNavigatorGoods()
	local dojo = data.dojo
	if self._activityNodes[tostring(dojo.type)]  then
		self:RefreshActivityNode(data)
	else
		self:CreateActivityNode(data)
	end
end

function RegressionNewDialog:RefreshActivityNode(data)
	local dojo = data.dojo
	local node = self._activityNodes[tostring(dojo.type)]
	if node and not isNull(node.go) and node.scr then
		self:SetCanvasEnabled(node, true)
		node.scr:Refresh(dojo, self)
		node.scr:RefreshTopGoods()
	end
end

---创建一个活动页面
---@param data table 页面数据
---@param cb function 回调
function RegressionNewDialog:CreateActivityNode(data, cb)
	CfUtils.StartCoroutineWithBlocker(function()
		xTry(function()
			local go = nil
			local dojo = data.dojo
			if dojo.prefabPath then
				local path = string.format("%s%s.prefab", dojo.prefabPath, tostring(RegressionActivityConstants.FunctionId))
				go = GameUtils.LoadBundleAsync(path, self.RewardRoot.gameObject, false)
			else
				go = GameUtils.LoadBundleAsyncById(dojo.prefabId, self.RewardRoot.gameObject, false, true)
			end
			local scr = CfUtils.GetLuaScr(go, dojo.scrPath)
			local node = {
				go = go,
				scr = scr,
			}
			self._activityNodes[tostring(dojo.type)] = node
			self:RefreshActivityNode(data)
			
			if cb then
				cb()
			end
		end)
	end)
end

function RegressionNewDialog:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		RegressionUtils.GetRegressMgr():RequestHomeDojo(function()
			self:RefreshSelf()
		end)
	end))
	return coWait
end

function RegressionNewDialog:SetTimeShow()
	local dojo = RegressionUtils.GetRegressMgr():GetHomeDojo()
	--region 时间
	local startTime =  dojo.startTime
	local closeTime =  dojo.closeTime
	CfUtils.FillText(self.TxtTime, self:GetShowTimeTxt(startTime, closeTime))
end

function RegressionNewDialog:GetShowTimeTxt(startTime ,endTime)
	return GameUtils.CheckUTCTimeformat(GameUtils.l10nTimeData("%m/%d", startTime).."-"..GameUtils.l10nTimeData("%m/%d", endTime))
end

---刷新自身
function RegressionNewDialog:RefreshSelf()
	self:SetTimeShow()
	self:InitToggleData()
	self:FillSelf()
end

function RegressionNewDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		for _, node in pairs(self._activityNodes) do
			if not isNull(node.go) then
				KTool.SafeDelete(node.go.gameObject, true)
			end
		end
		---更新主界面按钮红点
		RegressionUtils.GetRegressMgr():UpdateRegressHomeRedPoint()
		self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
		self:Delete()
		self = nil --lua层的gc需要
	end))
	return coWait
end

function RegressionNewDialog:SetCanvasEnabled(node, enabled)
	if isNull(checkTable(node).go) then return end
	
	local canvas = KTool.GetOrAddComponent(node.go, typeof(CS.UnityEngine.Canvas))
	canvas.enabled = enabled
	
	if node.scr and node.scr.SetEnabled then
		node.scr:SetEnabled(enabled)
	end
end

function RegressionNewDialog:RefreshRedPoint(index)
	local redPoint = self:GetRedPointStatus(index)
	---@type CommonTabToggleLeft
	local scr = CfUtils.GetLuaScr(self.TabLeftGroup, TabGroupPath)
	if scr then
		scr:FreshTabRedPointByIndex(index - 1, redPoint)
	end
end

return RegressionNewDialog
